// WorkerProfilesSchema returns the schema of worker_profiles.
func WorkerProfilesSchema() *schema.Table { return &workerProfilesTable }

// As returns a handle that references worker_profiles under its own alias.
func (t *WorkerProfilesTable) As(alias string) *WorkerProfilesTable {
	return keel.Alias(t.Ref, alias, BuildWorkerProfiles)
}

// LicenseState is the belongs relation.
func (t *WorkerProfilesTable) LicenseState() *usstatedb.UsStatesTable {
	return keel.Path(t.Ref, 0, usstatedb.BuildUsStates)
}

// Get returns the worker_profiles row with the given key, or keel.ErrNotFound.
func (t *WorkerProfilesTable) Get(ctx context.Context, db *keel.DB, key pulid.ID) (*worker.WorkerProfile, error) {
	return t.Where(t.ID.Eq(key)).One(ctx, db)
}

